import json

def norm(path):
    if path == "/":
        return "/"
    parts = []
    for p in path.split("/"):
        if p == "" or p == ".":
            continue
        if p == "..":
            if parts:
                parts.pop()
            continue
        parts.append(p)
    return "/" + "/".join(parts)

def parent(path):
    p = norm(path)
    if p == "/":
        return None
    i = p.rfind("/")
    return "/" if i == 0 else p[:i]

def depth_from_root(path, root):
    p = norm(path)
    r = norm(root)
    if p == r:
        return 0
